#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *mark = malloc(sizeof *mark);
    if (mark == NULL) {
        return 1;
    }
    *mark = 78;
    printf("Mark: %d\n", *mark);
    free(mark);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    size_t count = 3;
    int *marks = malloc(count * sizeof *marks);
    if (marks == NULL) {
        return 1;
    }
    int total = 0;
    for (size_t i = 0; i < count; i++) {
        marks[i] = 60 + (int)i * 5;
        total += marks[i];
    }
    printf("Total: %d\n", total);
    free(marks);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int *make_mark(int initial)
{
    int *result = malloc(sizeof *result);
    if (result != NULL) {
        *result = initial;
    }
    return result;
}

int main(void)
{
    int *value = make_mark(85);
    if (value == NULL) {
        return 1;
    }
    printf("Returned mark: %d\n", *value);
    free(value);
    return 0;
}

